{"results": [{"id": "hp_doc_49a52deaf0ed5663851c80fc5a81a3907aa3ad74603b3709b0f3909fe50edcb4", "title": "Louis de Silvestre", "text": "Louis de Silvestre (23 June 1675 – 11 April 1760) was a French portrait and history painter. He was court painter to King Augustus II of Poland, and director of the Royal Academy of Arts in Dresden.", "score": 38.7088}, {"id": "hp_doc_e543dd2e1b57fb03d7f5b5cdd1d065af3c7c6c11d2640e63dc8722e5c22a46ef", "title": "Marie-Maximilienne de Silvestre", "text": "Marie-Maximilienne de Silvestre (1708–1798) was a French painter.", "score": 19.9469}, {"id": "hp_doc_a638108234c2e093962242caa263c803a54473d4baf26ce4a72be80d196cf789", "title": "Augustus II the Strong", "text": "Augustus II the Strong (German: \"August II. der Starke\" ; Polish: \"August II Mocny\" ; Lithuanian: \"Augustas II\" ; 12 May 1670 – 1 February 1733) of the Albertine line of the House of Wettin was Elector of Saxony (as Frederick Augustus I), Imperial Vicar and elected King of Poland and Grand Duke of Lithuania.", "score": 17.7905}], "remaining_searches": 2}
